import {enablePageSwipe} from './swipe.js';
import {loginPage} from './login.js';
import {loadAcademy,chapters} from './data.js';import {resolveRoute} from './navigation.js';import {readPreferences,savePreferences} from './preferences.js';
let storage;try{storage=localStorage}catch{storage={getItem:()=>null,setItem:()=>{throw Error()}}}let preferences=readPreferences(storage);const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');let state=await loadAcademy(window.StackUpAcademyAdapter);let previousFocus;
const nav=[['home','⌂','Início'],['journey','▤','Aprender'],['practice','♠','Praticar'],['evolution','↗','Jogar'],['profile','♙','Perfil']];
const heading=(tag,title,description)=>`<div class="page-heading"><div><span class="eyebrow">${tag}</span><h1>${title}</h1><p>${description}</p></div><span class="chapter-tag">SÉRIE 01</span></div>`;
const empty=(symbol,title,description)=>`<section class="empty"><div class="empty-symbol">${symbol}</div><h2>${title}</h2><p>${description}</p><a href="#journey" class="primary">EXPLORAR A JORNADA <span>→</span></a></section>`;
const nextApps=`<section class="next-apps"><span class="eyebrow">DEPOIS DO BÁSICO · A HISTÓRIA CONTINUA</span><h2>Aprender é o começo.</h2><p>O Academy prepara você para participar da mesa. Evolução, especialização e busca pelo domínio continuam nos demais apps StackUp Hold’em.</p><div class="next-grid">${[['HEROES','Descubra seu Poker DNA.'],['GRINDER EVO','Aprofunde suas decisões em Texas Hold’em.'],['REVOLUTION','Explore o jogo em simulações.'],['D ACTION','Identifique pontos de melhoria no Omaha.'],['WRAPS','Aprofunde suas decisões no Omaha.'],['CHIPS UP','Desenvolva a gestão do seu bankroll.']].map(([name,desc])=>`<button class="next-app" data-series="${name}"><strong>${name}</strong><span>${desc}</span><i>↗</i></button>`).join('')}</div></section>`;
const quote=`<div class="quote">“Poker é um jogo que demora minutos para aprender. Mas leva uma vida para dominar.”<small>— MIKE SEXTON</small></div>`;
function openDialog(title,body){previousFocus=document.activeElement;document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-body').textContent=body;dialog.showModal()}
dialog.querySelector('.close').onclick=()=>dialog.close();dialog.querySelector('#dialog-action').onclick=()=>dialog.close();dialog.addEventListener('close',()=>previousFocus?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function home(){return heading('ACADEMY · A PRIMEIRA DESCOBERTA','Aprenda. Pratique. Jogue.','Entenda o jogo, pratique o básico e chegue à mesa com segurança.')+`<section class="hero"><div class="pokerinno-logo" role="img" aria-label="POKERINNO ACADEMY"><svg viewBox="0 0 32 38" aria-hidden="true"><path d="M16 1C12 8 1 13 1 23c0 7 8 10 13 5l-3 9h10l-3-9c5 5 13 2 13-5C31 13 20 8 16 1Z"/></svg><div><strong>POKERINNO</strong><span>ACADEMY</span></div></div><img class="hero-image" src="assets/pokerino-hero.webp" alt="Pokerinno recebe você em uma academia de poker iluminada em dourado"><div class="hero-copy"><span class="eyebrow">SUA JORNADA · APRENDER → PRATICAR → JOGAR</span><h2>APRENDER.<br>PRATICAR.<br><em>JOGAR.</em></h2><p>“Poker é um jogo que demora minutos para aprender. Mas leva uma vida para dominar.”</p><small class="quote-author">— MIKE SEXTON</small><a href="#journey" class="primary">COMEÇAR A APRENDER <span>→</span></a></div><div class="hero-note">COM POKERINNO, CADA PASSO CONTA.</div></section><div class="section-top"><h2>Qual será sua próxima descoberta?</h2><span>ESCOLHA SEU CAMINHO</span></div><div class="grid">${[['journey','▤','SUA BASE','Os primeiros passos para entender o jogo.'],['modalities','✧','MODALIDADES','Novas mesas. Diferentes possibilidades.'],['practice','♠','PRÁTICA','Um espaço para suas próximas decisões.'],['evolution','↗','SUA EVOLUÇÃO','Cada descoberta faz parte da sua história.']].map(([route,symbol,title,desc])=>`<a class="feature" href="#${route}"><span class="badge">${symbol}</span><span class="arrow">↗</span><h3>${title}</h3><p>${desc}</p></a>`).join('')}</div>`}
function render(){if(!location.hash||location.hash==='#login'){loginPage(app,'ACADEMY');return}document.body.classList.remove('login-screen');const route=resolveRoute(location.hash),active=route.startsWith('chapter')?'journey':route;for(const id of ['navigation','mobile-navigation'])document.getElementById(id).innerHTML=nav.map(([key,symbol,title])=>`<a class="${id==='navigation'?'nav-link ':''}${active===key?'active':''}" ${active===key?'aria-current="page"':''} href="#${key}"><span class="nav-symbol" aria-hidden="true">${symbol}</span>${title}</a>`).join('');document.documentElement.classList.toggle('reduced-motion',preferences.reducedMotion);
if(state.status==='error'){app.innerHTML=heading('SUA JORNADA','Vamos tentar novamente?','Sua navegação continua disponível.')+`<section class="empty"><h2>Não conseguimos carregar os conteúdos</h2><p>${state.error}</p><button class="primary" data-retry>TENTAR NOVAMENTE →</button></section>`;return}
if(route==='home')app.innerHTML=home();
else if(route==='journey')app.innerHTML=heading('O MAPA · SÉRIE 01','APRENDER → PRATICAR → JOGAR','Aprenda o essencial para acompanhar o jogo e participar da mesa.')+`<div class="list">${chapters.map(c=>`<a class="chapter" href="#chapter/${c.id}"><span class="number">0${c.order}</span><div><h3>${String(c.title).toUpperCase()}</h3><p>${c.description}</p></div><span class="status">Aulas em preparação<br>↗</span></a>`).join('')}</div>`+quote+nextApps;
else if(route.startsWith('chapter/')){const c=chapters.find(c=>c.id===route.split('/')[1]);app.innerHTML=`<a href="#journey" class="back">← Voltar à jornada</a>`+heading(`CAPÍTULO 0${c.order}`,c.title,c.description)+empty('▤','Seu próximo capítulo está sendo preparado.','As aulas aparecerão aqui quando o conteúdo da jornada estiver disponível. Seu aprendizado começa com uma base bem construída.')+quote}
else if(route==='modalities')app.innerHTML=heading('NOVOS CAMINHOS','Um jogo. Muitas possibilidades.','Descubra as diferentes formas de viver o poker.')+empty('✧','Novas mesas estão a caminho.','As modalidades e seus percursos serão apresentados aqui quando os conteúdos estiverem disponíveis.')+quote;
else if(route==='practice')app.innerHTML=heading('DA DESCOBERTA À DECISÃO','Pratique o básico.','Entenda a dinâmica antes de enfrentar a mesa.')+`<div class="grid">${[['◷','TREINO RÁPIDO','Pratique as decisões básicas.'],['☷','TREINO PERSONALIZADO','Reforce o que você aprendeu.'],['♜','DESAFIOS','Confira sua compreensão do jogo.'],['♠','REVISÃO DE MÃOS','Entenda o básico das suas decisões.']].map(([s,t,d])=>`<button class="feature" data-pending="${t}"><span class="badge">${s}</span><span class="arrow">↗</span><h3>${String(t).toUpperCase()}</h3><p>${d}</p></button>`).join('')}</div>`+empty('♠','As primeiras decisões estão a caminho.','Quando os treinos estiverem disponíveis, você encontrará aqui seus desafios e a revisão das suas decisões.');
else if(route==='evolution')app.innerHTML=heading('SUA HISTÓRIA','Sua preparação para a mesa.','Acompanhe os fundamentos que você está aprendendo.')+empty('↗','Sua história ainda vai começar.','Você ainda não possui aulas concluídas, treinos ou conquistas. O progresso aparecerá a partir das suas atividades reais.')+quote+nextApps;
else if(route==='profile')app.innerHTML=heading('DO SEU JEITO','Seu espaço no Academy.','Pequenos ajustes para acompanhar a sua jornada.')+`<section class="empty"><div class="empty-symbol">♙</div><h2>Olá, explorador.</h2><p>Você está conhecendo o Academy. Conecte sua conta quando o acesso estiver disponível.</p><button class="primary" data-login>ACESSAR MINHA CONTA →</button></section><div class="setting"><div><h3>Sons da jornada</h3><p>Preferência preparada para as experiências com áudio.</p></div><input type="checkbox" id="sound" aria-label="Sons da jornada" ${preferences.sound?'checked':''}></div><div class="setting"><div><h3>Reduzir movimentos</h3><p>Uma navegação mais tranquila, com menos animações.</p></div><input type="checkbox" id="reducedMotion" aria-label="Reduzir movimentos" ${preferences.reducedMotion?'checked':''}></div><div class="setting"><div><h3>Privacidade e conta</h3><p>Conta e sincronização disponíveis após a integração.</p></div><button class="quiet" data-login>CONSULTAR →</button></div>`;
else if(route==='welcome')app.innerHTML=home();
app.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.style.display='none'}));}
document.addEventListener('click',async e=>{const help=e.target.closest('[data-help]'),pending=e.target.closest('[data-pending]');const series=e.target.closest('[data-series]');if(series)openDialog(series.dataset.series,'Este é um dos próximos caminhos da série StackUp Hold’em. Cada app tem sua própria proposta. O acesso será conectado quando esse app estiver disponível nesta jornada.');if(help)openDialog('Oi! Eu sou o Pokerinno.','Vou ajudar você a entender o jogo, praticar o básico e chegar à mesa sabendo o que está acontecendo. O Academy prepara o iniciante; a especialização e a busca pelo domínio continuam nos demais apps da série StackUp Hold’em.');if(pending)openDialog(pending.dataset.pending,'Este espaço está pronto para receber os treinos. Assim que os desafios estiverem disponíveis, você poderá praticar por aqui.');if(e.target.closest('[data-login]'))location.hash='login';if(e.target.closest('[data-retry]')){state=await loadAcademy(window.StackUpAcademyAdapter);render()}});
document.addEventListener('change',e=>{if(['sound','reducedMotion'].includes(e.target.id)){preferences[e.target.id]=e.target.checked;const saved=savePreferences(storage,preferences);document.documentElement.classList.toggle('reduced-motion',preferences.reducedMotion);if(!saved)openDialog('Preferência aplicada','Seu navegador não permitiu salvar este ajuste. Ele permanece ativo durante esta visita.')}});window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'})});render();

enablePageSwipe(nav.map(item=>item[0]));
